// Pass the raw Apify tweet through as-is (all fields — likes, retweets,
// views, author, media, etc.) so the WordPress endpoint gets everything.
// Only drops items with no usable tweet id/text.
return items
  .filter(item => item.json && item.json.id && (item.json.text || item.json.fullText))
  .map(item => ({ json: item.json }));

